import { AccessManifestError, POSTGRES_IDENTIFIER_LIMIT, type AccessCatalog } from './access-manifest.ts';

/** The file sync:supabase writes, and orders directly after the core access SQL (A21). */
export const ACCESS_GENERATED_FILE = 'access-generated.sql';

/** The core access SQL the generated file depends on. */
export const ACCESS_CORE_FILE = '01-access.sql';

/**
 * The SQL for every module's access declaration: the permission catalog, and for each
 * entity-level scope its assignment table, policies and functions
 * (docs/ACCESS-CONTROL.md §2.2, §3.2).
 *
 * Returns null when no manifest declares access, so a project without it gets no file.
 *
 * The output is deterministic, byte for byte, for the same catalog. sync:supabase decides
 * whether a supplemental file still needs a migration by searching every migration for its
 * text, so output that varied between runs would add a migration on every sync.
 *
 * Every statement is re-runnable, because an edited supplemental file is carried forward in
 * full into a new migration: `create table if not exists` with `add column if not exists` for
 * each column (so a regenerated file upgrades an older table), `create or replace function`,
 * `drop policy if exists`.
 */
export function generateAccessSql(catalog: AccessCatalog): string | null {
  if (catalog.permission.size === 0) return null;

  for (const scope of catalog.entity) {
    for (const identifier of entityIdentifiers(scope)) {
      if (identifier.length > POSTGRES_IDENTIFIER_LIMIT) {
        throw new AccessManifestError(
          catalog.source.get(scope) ?? 'a manifest',
          `scope \`${scope}\` is too long: it generates \`${identifier}\`, over Postgres's ` +
            `${POSTGRES_IDENTIFIER_LIMIT}-character identifier limit`,
        );
      }
    }
  }

  const sections = [
    header(),
    permissionCatalog(catalog),
    ...catalog.entity.map(entitySql),
    currentUserScopesSql(catalog.entity),
  ];
  return sections.join('\n') + '\n';
}

function header(): string {
  return `-- ============================================================
-- Generated by sveltebuilder sync:supabase from each registry manifest's \`access\` key.
-- Do not edit: change the manifest and run sync again. See docs/ACCESS-CONTROL.md §4.
--
-- Applied directly after ${ACCESS_CORE_FILE}, whose helpers it calls, and before every
-- module's own policies, which call the functions defined here (A21).
-- ============================================================
`;
}

function permissionCatalog(catalog: AccessCatalog): string {
  const rows = [...catalog.permission.keys()]
    .sort()
    .flatMap((scope) => [...(catalog.permission.get(scope) ?? [])].sort().map((action) => `  ('${scope}', '${action}')`));

  // In this file rather than the seed: the role_assignment trigger and every seeded role
  // depend on these rows, and \`supabase db push\` never runs the seed (A11).
  return `-- ── Permission catalog ────────────────────────────────────────────────────────

insert into public.permission (scope, action) values
${rows.join(',\n')}
on conflict do nothing;
`;
}

/**
 * current_user_scopes(), replacing 01-access.sql's version with one that also counts assignments
 * on single rows of each entity scope (A24): someone given one article holds the article scope
 * as far as reaching the admin area and its menu goes.
 */
function currentUserScopesSql(entityScopes: string[]): string {
  const entityUnions = entityScopes
    .map(
      (scope) => `
  union
  select p.scope
  from public.${scope}_role_assignment a
  join public.role_permission rp on rp.role_id = a.role_id
  join public.permission p on p.id = rp.permission_id
  where p.scope = '${scope}'
    and (a.expires_at is null or a.expires_at > now())
    and (
      a.user_account_id = (select public.current_user_id())
      or a.user_group_id = any ((select public.current_user_group_ids())::integer[])
    )`
    )
    .join('');

  return `-- ── current_user_scopes() ─────────────────────────────────────────────────────
--
-- Every scope the current user may do anything in, counting assignments on single rows of
-- ${entityScopes.length > 0 ? entityScopes.join(', ') : 'no entity scope'} as well as broad ones.
-- Replaces the core version in ${ACCESS_CORE_FILE}.

create or replace function public.current_user_scopes()
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(distinct held.scope order by held.scope), '{}')
  from (
  select p.scope
  from public.permission p
  where coalesce((select public.current_user_admin()), false)
     or exists (
       select 1
       from public.role_assignment ra
       join public.role_permission rp on rp.role_id = ra.role_id
       where rp.permission_id = p.id
         and (ra.scope is null or ra.scope = p.scope)
         and (ra.expires_at is null or ra.expires_at > now())
         and (
           ra.user_account_id = (select public.current_user_id())
           or ra.user_group_id = any ((select public.current_user_group_ids())::integer[])
         )
     )${entityUnions}
  ) held
$$;
`;
}

/** Every identifier an entity scope generates, so none can exceed Postgres's limit unnoticed. */
function entityIdentifiers(scope: string): string[] {
  const table = `${scope}_role_assignment`;
  return [
    table,
    `${scope}_id`,
    `${table}_one_principal`,
    `uq_${table}`,
    `idx_${table}_${scope}_id`,
    `idx_${table}_user_account_id`,
    `idx_${table}_user_group_id`,
    `${table}_read`,
    `current_user_${scope}_ids`,
    `current_user_${scope}_actions`,
    `create_${table}`,
    `delete_${table}`,
    `list_${scope}_access`,
    `list_${scope}_principal`,
  ];
}

function entitySql(scope: string): string {
  const table = `${scope}_role_assignment`;
  const fk = `${scope}_id`;
  const held = `current_user_${scope}_ids`;
  const actions = `current_user_${scope}_actions`;

  return `-- ── ${scope} ${'─'.repeat(Math.max(0, 74 - scope.length))}
--
-- Assignments of a role on one ${scope} row, and the functions that read them. The foreign key
-- takes the type of public.${scope}'s primary key, read when this runs, so the table matches
-- whatever the entity uses. Deleting the row deletes its assignments.

do $$
declare
  v_type text;
begin
  select format_type(a.atttypid, a.atttypmod) into v_type
  from pg_index i
  join pg_attribute a on a.attrelid = i.indrelid and a.attnum = i.indkey[0]
  where i.indrelid = 'public.${scope}'::regclass and i.indisprimary and i.indnatts = 1;

  if v_type is null then
    raise exception 'access: public.${scope} has no single-column primary key to grant on';
  end if;

  execute format($sql$
    create table if not exists public.${table} (
      id               integer generated always as identity primary key,
      ${fk.padEnd(16)} %1$s not null references public.${scope}(id) on delete cascade,
      role_id          integer not null references public.role(id) on delete cascade,
      user_account_id  bigint references public.user_account(id) on delete cascade,
      user_group_id    integer references public.user_group(id) on delete cascade,
      granted_by       bigint references public.user_account(id) on delete set null,
      granted_at       timestamptz not null default now(),
      expires_at       timestamptz,
      constraint ${table}_one_principal
        check (num_nonnulls(user_account_id, user_group_id) = 1),
      constraint uq_${table}
        unique nulls not distinct (${fk}, role_id, user_account_id, user_group_id)
    );
    alter table public.${table}
      add column if not exists ${fk} %1$s not null references public.${scope}(id) on delete cascade,
      add column if not exists role_id integer not null references public.role(id) on delete cascade,
      add column if not exists user_account_id bigint references public.user_account(id) on delete cascade,
      add column if not exists user_group_id integer references public.user_group(id) on delete cascade,
      add column if not exists granted_by bigint references public.user_account(id) on delete set null,
      add column if not exists granted_at timestamptz not null default now(),
      add column if not exists expires_at timestamptz;
  $sql$, v_type);
end $$;

create index if not exists idx_${table}_${fk} on public.${table} (${fk});
create index if not exists idx_${table}_user_account_id on public.${table} (user_account_id);
create index if not exists idx_${table}_user_group_id on public.${table} (user_group_id);

-- The ${scope} ids on which the current user holds \`p_action\` through an unexpired assignment on
-- that row, their own or a group's. Policies call it as
-- \`id = any ((select public.${held}('update'))::bigint[])\` (A14).
create or replace function public.${held}(p_action text)
returns bigint[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(distinct a.${fk}::bigint), '{}')
  from public.${table} a
  join public.role_permission rp on rp.role_id = a.role_id
  join public.permission p on p.id = rp.permission_id
  where p.scope = '${scope}'
    and p.action = p_action
    and (a.expires_at is null or a.expires_at > now())
    and (
      a.user_account_id = (select public.current_user_id())
      or a.user_group_id = any ((select public.current_user_group_ids())::integer[])
    )
$$;

-- Every action the current user holds on each given ${scope}, from every target width: as an
-- administrator, through a global or scope assignment, or through an assignment on that row.
-- For showing and hiding controls, and for the sharing check below. Never called from a policy.
create or replace function public.${actions}(p_${scope}_ids bigint[])
returns table (${fk} bigint, action text)
language sql
stable
security definer
set search_path = ''
as $$
  with requested as (
    select distinct unnest(p_${scope}_ids) as id
  ),
  broad as (
    select p.action
    from public.permission p
    where p.scope = '${scope}'
      and public.current_user_can('${scope}', p.action)
  ),
  direct as (
    select a.${fk}::bigint as id, p.action
    from public.${table} a
    join public.role_permission rp on rp.role_id = a.role_id
    join public.permission p on p.id = rp.permission_id
    where p.scope = '${scope}'
      and a.${fk} = any (p_${scope}_ids)
      and (a.expires_at is null or a.expires_at > now())
      and (
        a.user_account_id = (select public.current_user_id())
        or a.user_group_id = any ((select public.current_user_group_ids())::integer[])
      )
  )
  select r.id, b.action from requested r cross join broad b
  union
  select d.id, d.action from direct d
$$;

-- Gives a role on one ${scope}. The caller must hold \`share\` on it, at any width, and every
-- permission the role holds on ${scope}, so nobody can grant more than they have (A12). Only the
-- role's ${scope} permissions apply at this target (A3).
create or replace function public.create_${table}(
  p_${fk}          bigint,
  p_role_id         integer,
  p_user_account_id bigint,
  p_user_group_id   integer,
  p_expires_at      timestamptz default null
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_held text[];
  v_role_assignment_id integer;
begin
  select coalesce(array_agg(h.action), '{}') into v_held
  from public.${actions}(array[p_${fk}]) h;

  if not ('share' = any (v_held)) then
    raise exception 'sharing this ${scope} requires ${scope}.share on it' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.role_permission rp
    join public.permission p on p.id = rp.permission_id
    where rp.role_id = p_role_id and p.scope = '${scope}'
  ) then
    raise exception 'that role holds no permission on ${scope}' using errcode = '22023';
  end if;

  if exists (
    select 1 from public.role_permission rp
    join public.permission p on p.id = rp.permission_id
    where rp.role_id = p_role_id and p.scope = '${scope}' and not (p.action = any (v_held))
  ) then
    raise exception 'that role holds ${scope} permissions you do not hold on it' using errcode = '42501';
  end if;

  insert into public.${table}
    (${fk}, role_id, user_account_id, user_group_id, granted_by, expires_at)
  values
    (p_${fk}, p_role_id, p_user_account_id, p_user_group_id, (select public.current_user_id()), p_expires_at)
  returning id into v_role_assignment_id;

  return v_role_assignment_id;
end;
$$;

-- Removes one assignment on a ${scope}. Any holder of \`share\` on it may remove any assignment on
-- it, including one they could not have made (E1 in docs/ACCESS-CONTROL-DECISIONS.md).
create or replace function public.delete_${table}(p_role_assignment_id integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_${fk} bigint;
begin
  select a.${fk} into v_${fk} from public.${table} a where a.id = p_role_assignment_id;
  if not found then
    raise exception 'no such role assignment';
  end if;

  if not exists (select 1 from public.${actions}(array[v_${fk}]) h where h.action = 'share') then
    raise exception 'removing access to this ${scope} requires ${scope}.share on it' using errcode = '42501';
  end if;

  delete from public.${table} where id = p_role_assignment_id;
end;
$$;

-- The access panel's rows for one ${scope} (A17): every assignment on it, expired ones included
-- so they can be removed, and every unexpired global or ${scope} assignment whose role holds a
-- ${scope} permission. \`${fk}\` is set only on the first kind, which is the only kind the panel
-- can remove. For an administrator or a holder of \`share\` on it.
create or replace function public.list_${scope}_access(p_${fk} bigint)
returns table (
  id                 integer,
  role_id            integer,
  user_account_id    bigint,
  email_address      text,
  user_group_id      integer,
  external           boolean,
  scope              text,
  ${fk.padEnd(18)} bigint,
  granted_by         bigint,
  granted_by_email_address text,
  granted_at         timestamptz,
  expires_at         timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
#variable_conflict use_column
begin
  if not exists (select 1 from public.${actions}(array[p_${fk}]) h where h.action = 'share') then
    raise exception 'viewing access to this ${scope} requires ${scope}.share on it' using errcode = '42501';
  end if;

  return query
  with assignment as (
    select a.id, a.role_id, a.user_account_id, a.user_group_id, '${scope}'::text as scope,
           a.${fk}::bigint as entity_id, a.granted_by, a.granted_at, a.expires_at
    from public.${table} a
    where a.${fk} = p_${fk}
    union all
    select ra.id, ra.role_id, ra.user_account_id, ra.user_group_id, ra.scope,
           null::bigint, ra.granted_by, ra.granted_at, ra.expires_at
    from public.role_assignment ra
    where (ra.scope is null or ra.scope = '${scope}')
      and (ra.expires_at is null or ra.expires_at > now())
      and exists (
        select 1 from public.role_permission rp
        join public.permission p on p.id = rp.permission_id
        where rp.role_id = ra.role_id and p.scope = '${scope}'
      )
  )
  select s.id, s.role_id, s.user_account_id, holder.email::text, s.user_group_id, g.external,
         s.scope, s.entity_id, s.granted_by, granter.email::text, s.granted_at, s.expires_at
  from assignment s
  left join public.user_account holder_account on holder_account.id = s.user_account_id
  left join auth.users holder on holder.id = holder_account.auth_user_id
  left join public.user_group g on g.id = s.user_group_id
  left join public.user_account granter_account on granter_account.id = s.granted_by
  left join auth.users granter on granter.id = granter_account.auth_user_id
  order by s.entity_id is null, s.granted_at, s.id;
end;
$$;

-- Everyone a sharer may give access to this ${scope}: every user, with their email address, and
-- every group. Its privacy cost is recorded as A20. For an administrator or a holder of \`share\`
-- on it.
create or replace function public.list_${scope}_principal(p_${fk} bigint)
returns table (
  user_account_id bigint,
  email_address   text,
  user_group_id   integer,
  external        boolean
)
language plpgsql
stable
security definer
set search_path = ''
as $$
#variable_conflict use_column
begin
  if not exists (select 1 from public.${actions}(array[p_${fk}]) h where h.action = 'share') then
    raise exception 'sharing this ${scope} requires ${scope}.share on it' using errcode = '42501';
  end if;

  return query
  select ua.id, u.email::text, null::integer, null::boolean
  from public.user_account ua
  join auth.users u on u.id = ua.auth_user_id
  union all
  select null::bigint, null::text, g.id, g.external
  from public.user_group g
  order by 2 nulls last, 3;
end;
$$;

-- Readable by an administrator, by the grantee (directly or through a group), and by anyone who
-- may share that ${scope}. Written by nobody: the two RPCs below are the only writers (A12).
alter table public.${table} enable row level security;

revoke insert, update, delete, truncate, references, trigger on public.${table}
  from anon, authenticated;

drop policy if exists "${table}_read" on public.${table};
create policy "${table}_read"
  on public.${table} for select
  to authenticated
  using (
    (select public.current_user_can('${scope}', 'share'))
    or user_account_id = (select public.current_user_id())
    or user_group_id = any ((select public.current_user_group_ids())::integer[])
    or ${fk} = any ((select public.${held}('share'))::bigint[])
  );

revoke execute on function public.${held}(text) from public, anon;
revoke execute on function public.${actions}(bigint[]) from public, anon;
revoke execute on function public.create_${table}(bigint, integer, bigint, integer, timestamptz) from public, anon;
revoke execute on function public.delete_${table}(integer) from public, anon;
revoke execute on function public.list_${scope}_access(bigint) from public, anon;
revoke execute on function public.list_${scope}_principal(bigint) from public, anon;

-- The ids helper is executable by anon too, because a policy's functions run as the role
-- querying and a policy written \`to anon\` may call it.
grant execute on function public.${held}(text) to authenticated, anon;
grant execute on function public.${actions}(bigint[]) to authenticated;
grant execute on function public.create_${table}(bigint, integer, bigint, integer, timestamptz) to authenticated;
grant execute on function public.delete_${table}(integer) to authenticated;
grant execute on function public.list_${scope}_access(bigint) to authenticated;
grant execute on function public.list_${scope}_principal(bigint) to authenticated;
`;
}
